export const statusUpdateRequestSchema = z.object({
  chatId: z.string().trim().min(1).max(240),
  namespaceId: identifierSchema,
  targetMessageId: z.string().trim().min(1).max(240),
  targetSwipeId: z.number().int().min(0).max(100_000),
  baseState: statusStateSchema,
  baseStateHash: z.string().regex(/^[a-f0-9]{64}$/),
  promptMessages: z.array(promptMessageSchema).min(1).max(200),
  messages: z.array(chatMessageSchema).min(1).max(500),
  validation: statusValidationConfigSchema,
  generationGroup: generationEndpointGroupSchema,
  failoverPolicy: failoverPolicySchema.default("confirm_ambiguous"),
  resumeAfterEndpointId: identifierSchema.optional(),
}).superRefine((request, context) => {
  const ids = request.messages.map((message) => message.id);
  if (new Set(ids).size !== ids.length) {
    context.addIssue({ code: "custom", path: ["messages"], message: "Status message IDs must be unique." });
  }
  if (!ids.includes(request.targetMessageId)) {
    context.addIssue({ code: "custom", path: ["targetMessageId"], message: "Target message must be supplied." });
  }
  if (JSON.stringify({
    baseState: request.baseState,
    promptMessages: request.promptMessages,
    messages: request.messages,
    validation: request.validation,
  }).length > MAX_EXTRACTION_CHARACTERS) {
    context.addIssue({ code: "custom", path: ["messages"], message: "Status update input is too large." });
  }
});

