export const retrievalQueryRequestSchema = z
  .object({
    collectionIds: z.array(identifierSchema).min(1).max(100),
    vectorCollectionIds: z.array(identifierSchema).max(100).optional(),
    sourceWeights: z.array(retrievalSourceWeightSchema).max(100).optional(),
    excludeSourceIds: z.array(z.string().trim().min(1).max(500)).max(10_000).optional(),
    query: z.string().trim().min(1).max(12_000),
    vectorEnabled: z.boolean().default(true),
    bm25Enabled: z.boolean().default(true),
    rerankEnabled: z.boolean().default(false),
    vectorTopK: z.number().int().min(1).max(200).default(30),
    bm25TopK: z.number().int().min(1).max(200).default(30),
    finalTopK: z.number().int().min(1).max(100).default(10),
    rerankTopK: z.number().int().min(1).max(100).default(30),
    failoverPolicy: failoverPolicySchema.default("confirm_ambiguous"),
    embeddingGroup: embeddingEndpointGroupSchema.optional(),
    rerankSet: rerankEndpointSetSchema.optional(),
    resumeAfter: z.object({
      embeddingEndpointId: identifierSchema.optional(),
      rerankEndpointId: identifierSchema.optional(),
    }).optional(),
  })
  .superRefine((request, context) => {
    if (!request.vectorEnabled && !request.bm25Enabled) {
      context.addIssue({ code: "custom", path: ["vectorEnabled"], message: "Enable vector or BM25 retrieval." });
    }
    if (request.vectorEnabled && !request.embeddingGroup) {
      context.addIssue({ code: "custom", path: ["embeddingGroup"], message: "Vector retrieval requires an embedding endpoint group." });
    }
    if (request.rerankEnabled && !request.rerankSet) {
      context.addIssue({ code: "custom", path: ["rerankSet"], message: "Reranking requires a rerank endpoint set." });
    }
    const collectionIds = new Set(request.collectionIds);
    const vectorCollectionIds = request.vectorCollectionIds ?? request.collectionIds;
    if (vectorCollectionIds.some((collectionId) => !collectionIds.has(collectionId))) {
      context.addIssue({
        code: "custom",
        path: ["vectorCollectionIds"],
        message: "Vector collection IDs must be a subset of collection IDs.",
      });
    }
    if (new Set(vectorCollectionIds).size !== vectorCollectionIds.length) {
      context.addIssue({
        code: "custom",
        path: ["vectorCollectionIds"],
        message: "Vector collection IDs must be unique.",
      });
    }
    if (request.sourceWeights) {
      const weightedIds = request.sourceWeights.map((source) => source.collectionId);
      if (new Set(weightedIds).size !== weightedIds.length) {
        context.addIssue({
          code: "custom",
          path: ["sourceWeights"],
          message: "Source weight collection IDs must be unique.",
        });
      }
      if (weightedIds.some((collectionId) => !collectionIds.has(collectionId))) {
        context.addIssue({
          code: "custom",
          path: ["sourceWeights"],
          message: "Source weights may only reference queried collections.",
        });
      }
    }
  });

