export function validateMemoryValues(
  columns: z.infer<typeof memoryColumnDefinitionSchema>[],
  rawValues: Record<string, unknown>,
  options: { partial?: boolean } = {},
): Record<string, unknown> {
  const knownColumns = new Map(columns.map((column) => [column.id, column]));
  const unknownColumns = Object.keys(rawValues).filter((key) => !knownColumns.has(key));
  if (unknownColumns.length > 0) throw new Error(`Unknown columns: ${unknownColumns.join(", ")}`);

  const values: Record<string, unknown> = {};
  for (const column of columns) {
    const supplied = Object.hasOwn(rawValues, column.id);
    if (options.partial && !supplied) continue;
    let value = rawValues[column.id];
    if ((value === undefined || value === null || value === "") && column.defaultValue !== undefined) {
      value = structuredClone(column.defaultValue);
    }
    if (value === undefined || value === null || value === "") {
      if (column.required && !options.partial) throw new Error(`Missing required column: ${column.name}`);
      continue;
    }

    switch (column.type) {
      case "text":
      case "long_text":
        if (typeof value !== "string") throw new Error(`${column.name} must be text.`);
        break;
      case "number":
        if (typeof value !== "number" || !Number.isFinite(value)) {
          throw new Error(`${column.name} must be a finite number.`);
        }
        break;
      case "boolean":
        if (typeof value !== "boolean") throw new Error(`${column.name} must be true or false.`);
        break;
      case "date":
        if (typeof value !== "string" || Number.isNaN(Date.parse(value))) {
          throw new Error(`${column.name} must be a valid date string.`);
        }
        break;
      case "enum":
        if (typeof value !== "string" || !column.enumValues?.includes(value)) {
          throw new Error(`${column.name} must be one of: ${column.enumValues?.join(", ") ?? ""}.`);
        }
        break;
      case "json":
        try {
          JSON.stringify(value);
        } catch {
          throw new Error(`${column.name} must be JSON-serializable.`);
        }
        break;
    }
    values[column.id] = value;
  }
  return values;
}
