import type { RetrievalEndpoint } from "../../shared/domain";
import { combineAbortSignals } from "../security/abort-signal";
import {
  MAX_PROVIDER_ERROR_BYTES,
  ProviderResponseTooLargeError,
  readResponseTextLimited,
  requestProvider,
} from "../security/provider-transport";
import { RetrievalProviderError } from "./endpoint-failover";

const MAX_EMBEDDING_RESPONSE_BYTES = 256 * 1024 * 1024;

function embeddingUrl(baseUrl: string): string {
  const normalized = baseUrl.replace(/\/+$/, "");
  if (/\/embeddings$/i.test(normalized)) return normalized;
  if (/\/v1$/i.test(normalized)) return `${normalized}/embeddings`;
  return `${normalized}/v1/embeddings`;
}

function statusError(status: number): RetrievalProviderError {
  return new RetrievalProviderError(`Provider returned HTTP ${status}.`, {
    ambiguous: status === 504,
    status,
    code: `PROVIDER_HTTP_${status}`,
  });
}

function networkCode(error: unknown): string {
  const direct = (error as { code?: unknown })?.code;
  if (typeof direct === "string") return direct;
  const cause = (error as { cause?: { code?: unknown } })?.cause;
  return typeof cause?.code === "string" ? cause.code : "";
}

async function providerJson(options: {
  endpoint: RetrievalEndpoint;
  url: string;
  body: unknown;
  signal: AbortSignal;
  maxResponseBytes?: number | undefined;
}): Promise<unknown> {
  const timeoutController = new AbortController();
  const timeout = setTimeout(() => {
    timeoutController.abort(new Error(`Provider timed out after ${options.endpoint.timeoutMs}ms.`));
  }, options.endpoint.timeoutMs);
  const combined = combineAbortSignals([options.signal, timeoutController.signal]);
  let response: Response | undefined;
  try {
    response = await requestProvider(options.url, {
      method: "POST",
      signal: combined.signal,
      headers: {
        "Content-Type": "application/json",
        ...(options.endpoint.apiKey ? { Authorization: `Bearer ${options.endpoint.apiKey}` } : {}),
      },
      body: JSON.stringify(options.body),
    });
    const text = await readResponseTextLimited(
      response,
      response.ok ? options.maxResponseBytes : MAX_PROVIDER_ERROR_BYTES,
    );
    if (!response.ok) throw statusError(response.status);
    try {
      return JSON.parse(text) as unknown;
    } catch {
      throw new RetrievalProviderError("Provider returned invalid JSON.", {
        ambiguous: true,
        status: response.status,
        code: "INVALID_PROVIDER_JSON",
      });
    }
  } catch (error) {
    if (options.signal.aborted) throw options.signal.reason ?? error;
    if (error instanceof RetrievalProviderError) throw error;
    if (timeoutController.signal.aborted) {
      throw new RetrievalProviderError(
        `Provider timed out after ${options.endpoint.timeoutMs}ms. The request may still have completed and been billed.`,
        { ambiguous: true, code: "PROVIDER_TIMEOUT" },
      );
    }
    if (error instanceof ProviderResponseTooLargeError) {
      throw new RetrievalProviderError(error.message, {
        ambiguous: true,
        status: response?.status,
        code: "PROVIDER_RESPONSE_TOO_LARGE",
      });
    }
    const code = networkCode(error);
    if (["ECONNREFUSED", "ENOTFOUND", "EAI_AGAIN", "ERR_INVALID_URL"].includes(code)) {
      throw new RetrievalProviderError(
        `Provider connection failed before a response was accepted${code ? ` (${code})` : ""}.`,
        { ambiguous: false, code: code || "PROVIDER_CONNECTION_FAILED" },
      );
    }
    throw new RetrievalProviderError(
      "Provider connection ended without a final response.",
      { ambiguous: true, code: "PROVIDER_CONNECTION_AMBIGUOUS" },
    );
  } finally {
    clearTimeout(timeout);
    combined.dispose();
  }
}

export async function requestEmbeddings(options: {
  endpoint: RetrievalEndpoint;
  texts: string[];
  expectedDimensions: number;
  signal: AbortSignal;
}): Promise<number[][]> {
  const estimatedResponseBytes = options.texts.length * options.expectedDimensions * 24 + 1024 * 1024;
  const response = await providerJson({
    endpoint: options.endpoint,
    url: embeddingUrl(options.endpoint.baseUrl),
    signal: options.signal,
    body: { model: options.endpoint.model, input: options.texts },
    maxResponseBytes: Math.min(
      MAX_EMBEDDING_RESPONSE_BYTES,
      Math.max(16 * 1024 * 1024, estimatedResponseBytes),
    ),
  });
  try {
    const payload = response as {
      data?: Array<{ index?: number; embedding?: unknown }>;
    };
    if (!Array.isArray(payload.data) || payload.data.length !== options.texts.length) {
      throw new Error("Embedding response count does not match the request.");
    }
    const ordered = [...payload.data].sort((left, right) => (left.index ?? 0) - (right.index ?? 0));
    if (ordered.some((item, index) => item.index !== index)) {
      throw new Error("Embedding response indices are missing or duplicated.");
    }
    return ordered.map((item, index) => {
      if (!Array.isArray(item.embedding)
        || item.embedding.length !== options.expectedDimensions
        || item.embedding.some((value) => typeof value !== "number" || !Number.isFinite(value))) {
        throw new Error(`Embedding ${index} does not match the configured ${options.expectedDimensions} dimensions.`);
      }
      return item.embedding as number[];
    });
  } catch (error) {
    throw new RetrievalProviderError(
      `Provider returned an unusable embedding response: ${error instanceof Error ? error.message : String(error)}`,
      { ambiguous: true, status: 200, code: "INVALID_EMBEDDING_RESPONSE" },
    );
  }
}

export async function requestRerank(options: {
  endpoint: RetrievalEndpoint;
  query: string;
  documents: string[];
  signal: AbortSignal;
}): Promise<Array<{ index: number; relevanceScore: number }>> {
  const response = await providerJson({
    endpoint: options.endpoint,
    url: options.endpoint.baseUrl,
    signal: options.signal,
    body: {
      model: options.endpoint.model,
      query: options.query,
      documents: options.documents,
    },
  });
  try {
    const payload = response as {
      results?: Array<{ index?: unknown; relevance_score?: unknown; score?: unknown }>;
    };
    if (!Array.isArray(payload.results)) throw new Error("Rerank response has no results array.");
    const results = payload.results.map((item) => ({
      index: Number(item.index),
      relevanceScore: Number(item.relevance_score ?? item.score),
    }));
    const indices = results.map((item) => item.index);
    if (results.some((item) => !Number.isInteger(item.index)
      || item.index < 0
      || item.index >= options.documents.length
      || !Number.isFinite(item.relevanceScore))
      || new Set(indices).size !== indices.length) {
      throw new Error("Rerank results contain an invalid index or score.");
    }
    return results;
  } catch (error) {
    throw new RetrievalProviderError(
      `Provider returned an unusable rerank response: ${error instanceof Error ? error.message : String(error)}`,
      { ambiguous: true, status: 200, code: "INVALID_RERANK_RESPONSE" },
    );
  }
}
