import { createHash } from "node:crypto";
import type { Request, RequestHandler, Response, Router } from "express";
import { ZodError } from "zod";

import {
  endpointTestRequestSchema,
  credentialCreateSchema,
  credentialMigrationSchema,
  credentialUpdateSchema,
  extractionRequestSchema,
  identifierSchema,
  retrievalCollectionInputSchema,
  retrievalDeleteRequestSchema,
  retrievalDocumentStatusRequestSchema,
  retrievalDocumentSyncRequestSchema,
  retrievalQueryContinueRequestSchema,
  retrievalQueryRequestSchema,
  retrievalRebuildRequestSchema,
  retrievalUpsertRequestSchema,
  summaryGenerationRequestSchema,
  statusUpdateRequestSchema,
  repairRequestSchema,
  systemDiagnosticRequestSchema,
} from "../../shared/schemas";
import { ECHOES_BUILD_INFO } from "../../shared/build-info";
import { API_PROTOCOL_VERSION } from "../../shared/domain";
import type { UserRuntime, UserRuntimeRegistry } from "../services/user-runtime-registry";

function errorStatus(error: unknown): number {
  if (error instanceof ZodError) return 400;
  const statusCode = (error as { statusCode?: unknown })?.statusCode;
  return typeof statusCode === "number" ? statusCode : 500;
}

function route(
  handler: (request: Request, response: Response) => Promise<void>,
  allowIncompatible = false,
): RequestHandler {
  return (request, response) => {
    const rawProtocol = request.headers?.["x-echoes-api-protocol"];
    const protocol = rawProtocol === undefined ? undefined : Number(rawProtocol);
    if (!allowIncompatible && protocol !== undefined
      && (!Number.isInteger(protocol) || protocol !== API_PROTOCOL_VERSION)) {
      response.status(426).json({
        error: `Echoes API protocol ${Number.isInteger(protocol) ? `v${protocol}` : "header is invalid"}; server protocol is v${API_PROTOCOL_VERSION}.`,
        code: "ECHOES_PROTOCOL_INCOMPATIBLE",
        build: ECHOES_BUILD_INFO,
      });
      return;
    }
    void handler(request, response).catch((error: unknown) => {
      const message = error instanceof Error ? error.message : String(error);
      if (!response.headersSent) response.status(errorStatus(error)).json({ error: message });
    });
  };
}

function extractionFingerprint(value: unknown): string {
  return createHash("sha256").update(JSON.stringify(value)).digest("hex");
}

function retrievalFingerprint(type: string, value: unknown): string {
  return createHash("sha256").update(type).update("\0").update(JSON.stringify(value)).digest("hex");
}

function retrieval(runtime: UserRuntime): NonNullable<UserRuntime["retrievalService"]> {
  if (runtime.subsystemErrors?.retrieval || !runtime.retrievalService) {
    throw Object.assign(new Error(runtime.subsystemErrors?.retrieval ?? "Retrieval runtime is unavailable."), {
      statusCode: 503,
      code: "RETRIEVAL_UNAVAILABLE",
    });
  }
  return runtime.retrievalService;
}

export function registerRoutes(options: {
  router: Router;
  runtimes: UserRuntimeRegistry;
}): void {
  const { router, runtimes } = options;

  router.get("/health", (_request, response) => {
    response.json({ ok: true, build: ECHOES_BUILD_INFO });
  });

  router.get(
    "/system/status",
    route(async (request, response) => {
      const runtime = await runtimes.forRequest(request);
      const rawProtocol = request.headers?.["x-echoes-api-protocol"];
      const protocol = rawProtocol === undefined ? undefined : Number(rawProtocol);
      response.json(await runtime.systemService.status(protocol));
    }, true),
  );

  router.post(
    "/system/diagnostics",
    route(async (request, response) => {
      const runtime = await runtimes.forRequest(request);
      const input = systemDiagnosticRequestSchema.parse(request.body ?? {});
      const job = await runtime.jobs.create(
        "system-diagnostics",
        () => runtime.systemService.diagnostics(input),
        { dedupeKey: retrievalFingerprint("system-diagnostics", input) },
      );
      response.status(202).json({ job });
    }, true),
  );

  router.post(
    "/system/repairs",
    route(async (request, response) => {
      const runtime = await runtimes.forRequest(request);
      const input = repairRequestSchema.parse(request.body);
      const job = await runtime.jobs.create(
        "system-repair",
        () => runtime.systemService.repair(input),
        { dedupeKey: retrievalFingerprint("system-repair", input) },
      );
      response.status(202).json({ job });
    }, true),
  );

  router.get(
    "/credentials",
    route(async (request, response) => {
      const runtime = await runtimes.forRequest(request);
      response.json({ credentials: await runtime.credentials.list() });
    }, true),
  );

  router.post(
    "/credentials",
    route(async (request, response) => {
      const runtime = await runtimes.forRequest(request);
      const credential = await runtime.credentials.create(credentialCreateSchema.parse(request.body));
      response.status(201).json({ credential });
    }, true),
  );

  router.post(
    "/credentials/migrate",
    route(async (request, response) => {
      const runtime = await runtimes.forRequest(request);
      const input = credentialMigrationSchema.parse(request.body);
      response.status(201).json({ credentials: await runtime.credentials.createMany(input.credentials) });
    }, true),
  );

  router.put(
    "/credentials/:credentialId",
    route(async (request, response) => {
      const runtime = await runtimes.forRequest(request);
      const credential = await runtime.credentials.update(
        identifierSchema.parse(String(request.params.credentialId)),
        credentialUpdateSchema.parse(request.body),
      );
      response.json({ credential });
    }, true),
  );

  router.delete(
    "/credentials/:credentialId",
    route(async (request, response) => {
      const runtime = await runtimes.forRequest(request);
      const deleted = await runtime.credentials.delete(
        identifierSchema.parse(String(request.params.credentialId)),
      );
      response.status(deleted ? 204 : 404).json(deleted ? undefined : { error: "Credential not found." });
    }, true),
  );

  router.get(
    "/retrieval/collections",
    route(async (request, response) => {
      const runtime = await runtimes.forRequest(request);
      response.json({ collections: await retrieval(runtime).listCollectionStats() });
    }),
  );

  router.post(
    "/retrieval/collections",
    route(async (request, response) => {
      const runtime = await runtimes.forRequest(request);
      const input = retrievalCollectionInputSchema.parse(request.body);
      const collection = await retrieval(runtime).createCollection(input);
      response.status(201).json({ collection });
    }),
  );

  router.delete(
    "/retrieval/collections/:collectionId",
    route(async (request, response) => {
      const runtime = await runtimes.forRequest(request);
      const collectionId = identifierSchema.parse(String(request.params.collectionId));
      const job = await runtime.jobs.create(
        "retrieval-collection-delete",
        async (context) => {
          context.report(0.1, "Deleting collection");
          return { deleted: await retrieval(runtime).deleteCollection(collectionId) };
        },
        { dedupeKey: retrievalFingerprint("collection-delete", collectionId) },
      );
      response.status(202).json({ job });
    }),
  );

  router.post(
    "/retrieval/documents/upsert",
    route(async (request, response) => {
      const runtime = await runtimes.forRequest(request);
      const input = retrievalUpsertRequestSchema.parse(request.body);
      const job = await runtime.jobs.create(
        "retrieval-document-upsert",
        (context) => retrieval(runtime).upsert(input, context),
        { dedupeKey: retrievalFingerprint("document-upsert", input) },
      );
      response.status(202).json({ job });
    }),
  );

  router.post(
    "/retrieval/documents/delete",
    route(async (request, response) => {
      const runtime = await runtimes.forRequest(request);
      const input = retrievalDeleteRequestSchema.parse(request.body);
      const job = await runtime.jobs.create(
        "retrieval-document-delete",
        async (context) => {
          context.report(0.1, "Deleting documents");
          return { deleted: await retrieval(runtime).deleteDocuments(input.documentIds) };
        },
        { dedupeKey: retrievalFingerprint("document-delete", input) },
      );
      response.status(202).json({ job });
    }),
  );

  router.post(
    "/retrieval/documents/status",
    route(async (request, response) => {
      const runtime = await runtimes.forRequest(request);
      const input = retrievalDocumentStatusRequestSchema.parse(request.body);
      response.json(await retrieval(runtime).documentStatus(input.documentIds));
    }),
  );

  router.post(
    "/retrieval/documents/sync",
    route(async (request, response) => {
      const runtime = await runtimes.forRequest(request);
      const input = retrievalDocumentSyncRequestSchema.parse(request.body);
      const job = await runtime.jobs.create(
        "retrieval-document-sync",
        (context) => retrieval(runtime).syncDocuments(input, context),
        { dedupeKey: retrievalFingerprint("document-sync", input) },
      );
      response.status(202).json({ job });
    }),
  );

  for (const [path, onlyUnready] of [
    ["/retrieval/indexes/repair", true],
    ["/retrieval/indexes/rebuild", false],
  ] as const) {
    router.post(
      path,
      route(async (request, response) => {
        const runtime = await runtimes.forRequest(request);
        const input = retrievalRebuildRequestSchema.parse(request.body);
        const job = await runtime.jobs.create(
          onlyUnready ? "retrieval-index-repair" : "retrieval-index-rebuild",
          (context) => retrieval(runtime).rebuild({ ...input, onlyUnready }, context),
          { dedupeKey: retrievalFingerprint(path, input) },
        );
        response.status(202).json({ job });
      }),
    );
  }

  router.post(
    "/retrieval/queries",
    route(async (request, response) => {
      const runtime = await runtimes.forRequest(request);
      const input = retrievalQueryRequestSchema.parse(request.body);
      const job = await runtime.jobs.create(
        "retrieval-query",
        (context) => retrieval(runtime).query(input, context),
        { dedupeKey: retrievalFingerprint("query", input), lane: "interactive" },
      );
      response.status(202).json({ job });
    }),
  );

  router.post(
    "/retrieval/queries/continue",
    route(async (request, response) => {
      const runtime = await runtimes.forRequest(request);
      const input = retrievalQueryContinueRequestSchema.parse(request.body);
      const job = await runtime.jobs.create(
        "retrieval-query-continuation",
        (context) => retrieval(runtime).continueQuery(input, context),
        {
          dedupeKey: retrievalFingerprint("query-continuation", input),
          lane: "interactive",
        },
      );
      response.status(202).json({ job });
    }),
  );

  router.post(
    "/retrieval/endpoints/test",
    route(async (request, response) => {
      const runtime = await runtimes.forRequest(request);
      const input = endpointTestRequestSchema.parse(request.body);
      const job = await runtime.jobs.create(
        `${input.kind}-endpoint-test`,
        (context) => input.kind === "generation"
          ? runtime.generationService.testEndpoint(input.endpoint, context)
          : retrieval(runtime).testEndpoint(input, context),
        { dedupeKey: retrievalFingerprint("endpoint-test", input) },
      );
      response.status(202).json({ job });
    }),
  );

  router.post(
    "/summaries/generate",
    route(async (request, response) => {
      const runtime = await runtimes.forRequest(request);
      const input = summaryGenerationRequestSchema.parse(request.body);
      const job = await runtime.jobs.create(
        "summary-generation",
        (context) => runtime.summaryService.generate(input, context),
        { dedupeKey: extractionFingerprint(input) },
      );
      response.status(202).json({ job });
    }),
  );

  router.post(
    "/status/updates",
    route(async (request, response) => {
      const runtime = await runtimes.forRequest(request);
      const input = statusUpdateRequestSchema.parse(request.body);
      const job = await runtime.jobs.create(
        "status-update",
        (context) => runtime.statusService.update(input, context),
        {
          dedupeKey: retrievalFingerprint("status-update", input),
          lane: "status",
        },
      );
      response.status(202).json({ job });
    }),
  );

  router.post(
    "/memory/extractions",
    route(async (request, response) => {
      const runtime = await runtimes.forRequest(request);
      const extractionRequest = extractionRequestSchema.parse(request.body);
      const job = await runtime.jobs.create(
        "structured-memory-extraction",
        (context) => runtime.extractionService.extract(extractionRequest, context),
        { dedupeKey: extractionFingerprint(extractionRequest) },
      );
      response.status(202).json({ job });
    }),
  );

  router.get(
    "/jobs/:jobId",
    route(async (request, response) => {
      const runtime = await runtimes.forRequest(request);
      const job = runtime.jobs.get(String(request.params.jobId));
      if (!job) {
        response.status(404).json({ error: "Job not found." });
        return;
      }
      response.json({ job });
    }),
  );

  router.post(
    "/jobs/:jobId/cancel",
    route(async (request, response) => {
      const runtime = await runtimes.forRequest(request);
      const cancelled = await runtime.jobs.cancel(String(request.params.jobId));
      response.status(cancelled ? 202 : 409).json({ cancelled });
    }),
  );
}
