import type { Router } from "express";

import { registerRoutes } from "./http/routes";
import { UserRuntimeRegistry } from "./services/user-runtime-registry";

const runtimes = new UserRuntimeRegistry();
let pruneTimer: NodeJS.Timeout | null = null;

export async function init(router: Router): Promise<void> {
  registerRoutes({ router, runtimes });
  pruneTimer = setInterval(() => {
    void runtimes.prune().catch((error) => {
      console.error(
        "[Echoes] Background job pruning failed:",
        error instanceof Error ? error.message : String(error),
      );
    });
  }, 60 * 60_000);
  pruneTimer.unref();
  console.log("[Echoes] Server plugin initialized.");
}

export async function exit(): Promise<void> {
  if (pruneTimer) clearInterval(pruneTimer);
  pruneTimer = null;
  await runtimes.flush();
}

export const info = {
  id: "echoes-memory",
  name: "Echoes Memory System",
  description: "Structured and semantic long-term memory for SillyTavern.",
};
