import { randomUUID } from "node:crypto";
import { mkdir, readdir, rename, rm, stat, writeFile } from "node:fs/promises";
import path from "node:path";

import { ECHOES_BUILD_INFO, protocolCompatible } from "../../shared/build-info";
import type {
  DiagnosticCheck,
  RepairRequest,
  RepairResult,
  RetrievalCollectionStats,
  SystemStatus,
} from "../../shared/domain";
import type { CredentialStore } from "./credential-store";

const STALE_TEMPORARY_FILE_MS = 10 * 60_000;

export interface SystemServiceOptions {
  dataDirectory: string;
  credentials: CredentialStore;
  subsystemErrors: Partial<Record<"jobs" | "retrieval", string>>;
  retrievalAvailable: () => boolean;
  retrievalStats?: (() => Promise<RetrievalCollectionStats[]>) | undefined;
  repairJobs?: (() => Promise<void>) | undefined;
}

export function runtimePlatformSupported(
  nodeVersion = process.versions.node,
  platform = process.platform,
  arch = process.arch,
): boolean {
  const [nodeMajor = Number.NaN, nodeMinor = Number.NaN] = nodeVersion
    .split(".")
    .map((part) => Number.parseInt(part, 10));
  return (platform === "win32" || platform === "linux")
    && arch === "x64"
    && (nodeMajor === 22 || nodeMajor === 24 || (nodeMajor === 20 && nodeMinor >= 9));
}

function check(
  id: string,
  title: string,
  state: DiagnosticCheck["state"],
  message: string,
  repairKind?: DiagnosticCheck["repairKind"],
): DiagnosticCheck {
  return { id, title, state, message, ...(repairKind ? { repairKind } : {}) };
}

export class SystemService {
  constructor(private readonly options: SystemServiceOptions) {}

  async status(clientProtocol?: number): Promise<SystemStatus> {
    const permissions = await this.options.credentials.permissions().catch(() => ({ exists: false, secure: false }));
    const credentialsReadable = await this.options.credentials.list().then(() => true, () => false);
    return {
      build: ECHOES_BUILD_INFO,
      protocolCompatible: protocolCompatible(clientProtocol),
      platform: {
        node: process.versions.node,
        platform: process.platform,
        arch: process.arch,
        supported: runtimePlatformSupported(),
      },
      bootstrap: {
        state: process.env.ECHOES_BOOTSTRAP_STATE === "degraded" ? "degraded" : "ready",
        ...(process.env.ECHOES_DEPENDENCY_HASH ? { dependencyHash: process.env.ECHOES_DEPENDENCY_HASH } : {}),
        ...(process.env.ECHOES_BOOTSTRAP_MESSAGE ? { message: process.env.ECHOES_BOOTSTRAP_MESSAGE } : {}),
      },
      subsystems: {
        credentials: credentialsReadable && permissions.secure ? "ready" : "degraded",
        jobs: this.options.subsystemErrors.jobs ? "degraded" : "ready",
        retrieval: this.options.retrievalAvailable()
          ? "ready"
          : this.options.subsystemErrors.retrieval ? "degraded" : "unavailable",
      },
      pendingMigrations: [],
    };
  }

  async diagnostics(input: {
    clientProtocol?: number | undefined;
    clientVersion?: string | undefined;
    settingsFormatVersion?: number | undefined;
    tavernHelper?: Record<string, boolean> | undefined;
    worldbook?: {
      formatVersions?: number[] | undefined;
      staleInjectionCount?: number | undefined;
      summaryIndexMismatches?: number | undefined;
    } | undefined;
    credentialIds?: string[] | undefined;
  } = {}): Promise<{ status: SystemStatus; checks: DiagnosticCheck[]; bundle: Record<string, unknown> }> {
    const status = await this.status(input.clientProtocol);
    if (input.settingsFormatVersion !== undefined && input.settingsFormatVersion < 2) {
      status.pendingMigrations.push("settings_format");
    }
    const permissions = await this.options.credentials.permissions().catch(() => ({ exists: false, secure: false }));
    let credentialStoreError = false;
    const credentials = await this.options.credentials.list().catch(() => {
      credentialStoreError = true;
      return [];
    });
    const credentialIds = new Set(credentials.map((credential) => credential.id));
    const missingCredentials = (input.credentialIds ?? []).filter((id) => !credentialIds.has(id));
    const referencedCredentials = input.credentialIds ? new Set(input.credentialIds) : null;
    const orphanCredentials = referencedCredentials
      ? credentials.filter((credential) => !referencedCredentials.has(credential.id))
      : [];
    const helperMissing = Object.entries(input.tavernHelper ?? {}).filter(([, available]) => !available).map(([name]) => name);
    const formatVersions = input.worldbook?.formatVersions ?? [];
    if (formatVersions.some((version) => version < 2)) status.pendingMigrations.push("summary_format");
    const temporaryFiles = await this.temporaryFileCount().catch(() => null);
    let collectionStatsError = false;
    let collectionStats: RetrievalCollectionStats[] = [];
    if (status.subsystems.retrieval === "ready" && this.options.retrievalStats) {
      try {
        collectionStats = await this.options.retrievalStats();
      } catch {
        collectionStatsError = true;
      }
    }
    const checks: DiagnosticCheck[] = [
      check("app_version", "Application version",
        !input.clientVersion ? "unavailable" : input.clientVersion === status.build.appVersion ? "pass" : "warning",
        !input.clientVersion
          ? "No client application version was submitted."
          : input.clientVersion === status.build.appVersion
            ? `Client and server are both Echoes ${status.build.appVersion}.`
            : `Client Echoes ${input.clientVersion} is connected to server Echoes ${status.build.appVersion}; protocol compatibility determines task availability.`),
      check("api_protocol", "API protocol", status.protocolCompatible ? "pass" : "fail",
        status.protocolCompatible ? "Client and server protocols are compatible." : "Client and server protocols are incompatible."),
      check("settings_format", "Settings format",
        input.settingsFormatVersion === undefined ? "unavailable" : input.settingsFormatVersion >= 2 ? "pass" : "warning",
        input.settingsFormatVersion === undefined
          ? "No client settings format was submitted."
          : `Client settings format is v${input.settingsFormatVersion}.`,
        input.settingsFormatVersion !== undefined && input.settingsFormatVersion < 2 ? "settings_format" : undefined),
      check("runtime_platform", "Runtime platform", status.platform.supported ? "pass" : "warning",
        status.platform.supported
          ? `${status.platform.platform}/${status.platform.arch}, Node ${status.platform.node}.`
          : `${status.platform.platform}/${status.platform.arch}, Node ${status.platform.node}; official support is Windows or Linux x64 on Node 20.9+, 22, or 24.`),
      check("data_directory", "Data directory", await this.dataDirectoryWritable() ? "pass" : "fail",
        "Echoes user data directory access checked."),
      check("credential_store", "Credential store", credentialStoreError ? "fail" : "pass",
        credentialStoreError ? "The credential store could not be read." : "The credential store is readable."),
      check("credential_permissions", "Credential permissions",
        credentialStoreError ? "unavailable" : permissions.secure ? "pass" : "fail",
        credentialStoreError
          ? "Credential permissions cannot be assessed until the store is readable."
          : permissions.secure ? "Credential permissions are restricted." : "Credential file permissions are too broad.",
        !credentialStoreError && !permissions.secure ? "credential_permissions" : undefined),
      check("credential_references", "Credential references",
        credentialStoreError ? "unavailable" : missingCredentials.length === 0 ? "pass" : "warning",
        credentialStoreError
          ? "Credential references cannot be checked until the store is readable."
          : missingCredentials.length === 0 ? "All submitted credential references exist." : `${missingCredentials.length} credential references are missing.`),
      check("orphan_credentials", "Orphan credentials",
        credentialStoreError || !referencedCredentials ? "unavailable" : orphanCredentials.length === 0 ? "pass" : "warning",
        credentialStoreError || !referencedCredentials
          ? "Orphan credentials cannot be assessed without a readable store and client references."
          : `${orphanCredentials.length} credentials are not referenced by current settings.`,
        !credentialStoreError && referencedCredentials && orphanCredentials.length > 0 ? "orphan_credentials" : undefined),
      check("jobs_file", "Durable jobs", this.options.subsystemErrors.jobs ? "fail" : "pass",
        this.options.subsystemErrors.jobs ?? "Durable job storage is available.",
        this.options.subsystemErrors.jobs ? "jobs_file" : undefined),
      check("temporary_files", "Temporary files",
        temporaryFiles === null ? "unavailable" : temporaryFiles === 0 ? "pass" : "warning",
        temporaryFiles === null ? "Temporary files could not be inspected." : `${temporaryFiles} stale temporary files found.`,
        temporaryFiles && temporaryFiles > 0 ? "temporary_files" : undefined),
      check("retrieval_runtime", "LanceDB retrieval", status.subsystems.retrieval === "ready" ? "pass" : "fail",
        this.options.subsystemErrors.retrieval ?? "Retrieval runtime is available."),
      check("collection_manifest", "Collection manifest",
        status.subsystems.retrieval !== "ready" ? "unavailable" : collectionStatsError ? "fail" : "pass",
        status.subsystems.retrieval !== "ready"
          ? "Collection metadata is unavailable while retrieval is degraded."
          : collectionStatsError ? "Collection metadata could not be read." : `${collectionStats.length} collections are readable.`),
      check("tavern_helper", "TavernHelper capabilities", helperMissing.length === 0 ? "pass" : "warning",
        helperMissing.length === 0 ? "Required client capabilities were reported." : `Missing: ${helperMissing.join(", ")}.`),
      check("worldbook_format", "Worldbook format", formatVersions.every((version) => version >= 2) ? "pass" : formatVersions.length ? "warning" : "unavailable",
        formatVersions.length ? `Observed formats: ${[...new Set(formatVersions)].join(", ")}.` : "No current-worldbook metadata was submitted.",
        formatVersions.some((version) => version < 2) ? "summary_format" : undefined),
      check("temporary_injections", "Temporary injections", (input.worldbook?.staleInjectionCount ?? 0) === 0 ? "pass" : "warning",
        `${input.worldbook?.staleInjectionCount ?? 0} stale temporary injections reported.`,
        (input.worldbook?.staleInjectionCount ?? 0) > 0 ? "temporary_injections" : undefined),
      check("summary_index", "Summary index consistency", (input.worldbook?.summaryIndexMismatches ?? 0) === 0 ? "pass" : "warning",
        `${input.worldbook?.summaryIndexMismatches ?? 0} summary index mismatches reported.`,
        (input.worldbook?.summaryIndexMismatches ?? 0) > 0 ? "retrieval_index" : undefined),
    ];
    const bundle = {
      build: status.build,
      platform: status.platform,
      bootstrap: status.bootstrap,
      subsystems: status.subsystems,
      checks,
      credentialCount: credentials.length,
      collections: collectionStats.map((item) => ({
        id: item.collection.id,
        documents: item.documents,
        ready: item.ready,
        pending: item.pending,
        failed: item.failed,
        ambiguous: item.ambiguous,
        dimensions: item.dimensions,
        vectorIndex: item.vectorIndex,
      })),
      generatedAt: new Date().toISOString(),
    };
    return { status, checks, bundle };
  }

  async repair(request: RepairRequest): Promise<RepairResult> {
    const completed: RepairResult["completed"] = [];
    const skipped: RepairResult["skipped"] = [];
    for (const kind of request.kinds) {
      if (kind === "credential_permissions") {
        await this.options.credentials.repairPermissions();
        completed.push(kind);
      } else if (kind === "orphan_credentials") {
        const ids = request.orphanCredentialIds ?? [];
        if (ids.length === 0) skipped.push({ kind, reason: "No orphan credential IDs were supplied." });
        else {
          for (const id of ids) await this.options.credentials.delete(id);
          completed.push(kind);
        }
      } else if (kind === "temporary_files") {
        await this.clearTemporaryFiles();
        completed.push(kind);
      } else if (kind === "jobs_file" && this.options.subsystemErrors.jobs) {
        await this.quarantine(path.join(this.options.dataDirectory, "jobs.json"));
        await this.options.repairJobs?.();
        delete this.options.subsystemErrors.jobs;
        completed.push(kind);
      } else {
        skipped.push({ kind, reason: "This repair requires current-chat confirmation or the existing index repair workflow." });
      }
    }
    const { checks } = await this.diagnostics();
    return { completed, skipped, checks };
  }

  private async dataDirectoryWritable(): Promise<boolean> {
    const probe = path.join(this.options.dataDirectory, `.echoes-write-probe.${process.pid}.${randomUUID()}.tmp`);
    try {
      await mkdir(this.options.dataDirectory, { recursive: true });
      await stat(this.options.dataDirectory);
      await writeFile(probe, "echoes", { encoding: "utf8", mode: 0o600 });
      await rm(probe, { force: true });
      return true;
    } catch {
      await rm(probe, { force: true }).catch(() => undefined);
      return false;
    }
  }

  private async clearTemporaryFiles(): Promise<void> {
    await Promise.all((await this.staleTemporaryFiles()).map((file) => rm(file, { force: true })));
  }

  private async temporaryFileCount(): Promise<number> {
    return (await this.staleTemporaryFiles()).length;
  }

  private async staleTemporaryFiles(): Promise<string[]> {
    await mkdir(this.options.dataDirectory, { recursive: true });
    const directories = [this.options.dataDirectory, path.join(this.options.dataDirectory, "retrieval")];
    const stale: string[] = [];
    for (const directory of directories) {
      const entries = await readdir(directory, { withFileTypes: true }).catch((error: NodeJS.ErrnoException) => {
        if (error.code === "ENOENT") return [];
        throw error;
      });
      for (const entry of entries) {
        if (!entry.isFile() || (!/\.tmp$/i.test(entry.name) && !/\.partial$/i.test(entry.name))) continue;
        const file = path.join(directory, entry.name);
        const metadata = await stat(file);
        if (Date.now() - metadata.mtimeMs > STALE_TEMPORARY_FILE_MS) stale.push(file);
      }
    }
    return stale;
  }

  private async quarantine(filePath: string): Promise<void> {
    try {
      await rename(filePath, `${filePath}.corrupt.${Date.now()}.${randomUUID()}`);
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
    }
  }
}
