import type {
  PromptMessageInput,
  StatusUpdateRequest,
  StatusUpdateResult,
} from "../../shared/domain";
import { statusPayloadSchema } from "../../shared/schemas";
import { applyStatusOperations, statusStateHash } from "../../shared/status-core";
import type { JobContext } from "../jobs/job-manager";
import { GenerationService } from "./generation-service";

export const STATUS_OUTPUT_PROTOCOL = `Return exactly one JSON object with this shape:
{"operations":[{"op":"set","path":["category","field"],"value":"new value","evidenceMessageIds":["message-id"]},{"op":"delete","path":["category","obsolete field"],"evidenceMessageIds":["message-id"]}]}
Use only set and delete operations. Every operation must cite one or more supplied message IDs that directly support it. Return {"operations":[]} when nothing changed. Do not use Markdown fences or include any text outside the JSON object.`;

export class StatusService {
  constructor(private readonly generation: GenerationService) {}

  async update(request: StatusUpdateRequest, context: JobContext): Promise<StatusUpdateResult> {
    if (await statusStateHash(request.baseState) !== request.baseStateHash) {
      throw Object.assign(new Error("Status base hash does not match the supplied state."), {
        statusCode: 400,
        code: "STATUS_BASE_HASH_MISMATCH",
      });
    }
    const providerMessages: PromptMessageInput[] = [
      ...request.promptMessages,
      { role: "user", content: STATUS_OUTPUT_PROTOCOL },
    ];
    context.report(0.1, "Waiting for status API");
    const generated = await this.generation.run({
      workflow: "status",
      group: request.generationGroup,
      policy: request.failoverPolicy,
      resumeAfterEndpointId: request.resumeAfterEndpointId,
      messages: providerMessages,
      context,
    });
    if (generated.decisionRequired) {
      return {
        outcome: "decision_required",
        operations: [],
        attempts: generated.attempts,
        decisionRequired: generated.decisionRequired,
      };
    }
    if (generated.state !== "succeeded" || !generated.value) {
      throw Object.assign(new Error(generated.message ?? "All status generation endpoints failed."), {
        statusCode: 502,
        code: "STATUS_ENDPOINTS_FAILED",
      });
    }
    context.report(0.82, "Validating status update");
    let payload: unknown;
    try {
      payload = JSON.parse(generated.value.trim());
    } catch {
      throw Object.assign(new Error("Status response must be one complete JSON object."), {
        statusCode: 502,
        code: "INVALID_STATUS_RESPONSE",
      });
    }
    const parsed = statusPayloadSchema.parse(payload);
    const state = applyStatusOperations({
      baseState: request.baseState,
      operations: parsed.operations,
      evidenceMessageIds: request.messages.map((message) => message.id),
      validation: request.validation,
    });
    const stateHash = await statusStateHash(state);
    context.report(0.99, `Validated ${parsed.operations.length} status operations`);
    return {
      outcome: "completed",
      operations: parsed.operations,
      state,
      stateHash,
      attempts: generated.attempts,
    };
  }
}
