import { randomUUID } from "node:crypto";
import { mkdir, readFile, rename, unlink, writeFile } from "node:fs/promises";
import path from "node:path";

import type { JobRecord } from "../../shared/domain";

export interface JobContext {
  jobId: string;
  signal: AbortSignal;
  report(progress: number, message: string): void;
}

export class AmbiguousJobError extends Error {
  readonly retryable = false;
  readonly code = "AMBIGUOUS_PROVIDER_OUTCOME";

  constructor(message: string) {
    super(message);
    this.name = "AmbiguousJobError";
  }
}

export interface JobPersistenceAdapter {
  prepare(filePath: string): Promise<void>;
  read(filePath: string): Promise<string>;
  writeAtomically(filePath: string, contents: string): Promise<void>;
}

const nodePersistenceAdapter: JobPersistenceAdapter = {
  async prepare(filePath) {
    await mkdir(path.dirname(filePath), { recursive: true });
  },
  read(filePath) {
    return readFile(filePath, "utf8");
  },
  async writeAtomically(filePath, contents) {
    const temporaryPath = `${filePath}.${process.pid}.${randomUUID()}.tmp`;
    try {
      await writeFile(temporaryPath, contents, "utf8");
      await rename(temporaryPath, filePath);
    } catch (error) {
      await unlink(temporaryPath).catch(() => undefined);
      throw error;
    }
  },
};

interface JobManagerOptions {
  filePath?: string;
  concurrency?: number;
  backgroundConcurrency?: number;
  interactiveConcurrency?: number;
  statusConcurrency?: number;
  persistence?: JobPersistenceAdapter;
  onPersistenceError?: (error: Error) => void;
}

export type JobLane = "background" | "interactive" | "status";

interface QueuedTask {
  jobId: string;
  task: (context: JobContext) => Promise<unknown>;
  controller: AbortController;
  dedupeKey?: string;
  lane: JobLane;
}

interface PersistedJobs {
  formatVersion: 1;
  jobs: JobRecord[];
}

function durableJobMessage(status: JobRecord["status"]): string {
  switch (status) {
    case "queued": return "Queued";
    case "running": return "Running";
    case "succeeded": return "Completed";
    case "cancelled": return "Cancelled";
    case "ambiguous": return "Provider outcome is ambiguous";
    case "failed": return "Failed";
  }
}

function durableErrorMessage(error: NonNullable<JobRecord["error"]>): string {
  return error.code.startsWith("PROVIDER_") || error.code === "AMBIGUOUS_PROVIDER_OUTCOME"
    ? "The provider request did not complete successfully."
    : "The job did not complete successfully.";
}

export class JobManager {
  private readonly jobs = new Map<string, JobRecord>();
  private readonly controllers = new Map<string, AbortController>();
  private readonly dedupeJobs = new Map<string, string>();
  private readonly finalizingJobs = new Set<string>();
  private readonly queues: Record<JobLane, QueuedTask[]> = {
    background: [],
    interactive: [],
    status: [],
  };
  private filePath: string | undefined;
  private readonly persistence: JobPersistenceAdapter;
  private readonly onPersistenceError: ((error: Error) => void) | undefined;
  private readonly concurrency: Record<JobLane, number>;
  private readonly activeCount: Record<JobLane, number> = {
    background: 0,
    interactive: 0,
    status: 0,
  };
  private initialized = false;
  private initializePromise: Promise<void> | null = null;
  private writeChain: Promise<void> = Promise.resolve();

  constructor(options: JobManagerOptions = {}) {
    this.filePath = options.filePath;
    this.persistence = options.persistence ?? nodePersistenceAdapter;
    this.onPersistenceError = options.onPersistenceError;
    this.concurrency = {
      background: Math.max(
        1,
        Math.floor(options.backgroundConcurrency ?? options.concurrency ?? 1),
      ),
      interactive: Math.max(1, Math.floor(options.interactiveConcurrency ?? 1)),
      status: Math.max(1, Math.floor(options.statusConcurrency ?? 1)),
    };
  }

  async initialize(): Promise<void> {
    if (this.initialized) return;
    if (this.initializePromise) return this.initializePromise;
    this.initializePromise = this.load();
    try {
      await this.initializePromise;
      this.initialized = true;
    } finally {
      this.initializePromise = null;
    }
  }

  async create<TResult>(
    type: string,
    task: (context: JobContext) => Promise<TResult>,
    options: { dedupeKey?: string; lane?: JobLane } = {},
  ): Promise<JobRecord<TResult>> {
    await this.initialize();

    if (options.dedupeKey) {
      const existingId = this.dedupeJobs.get(options.dedupeKey);
      const existing = existingId ? this.jobs.get(existingId) : undefined;
      if (existing && ["queued", "running"].includes(existing.status)) {
        return structuredClone(existing) as JobRecord<TResult>;
      }
    }

    const now = new Date().toISOString();
    const job: JobRecord<TResult> = {
      id: randomUUID(),
      type,
      status: "queued",
      progress: 0,
      message: "Queued",
      createdAt: now,
      updatedAt: now,
    };
    const controller = new AbortController();
    this.jobs.set(job.id, job);
    this.controllers.set(job.id, controller);
    if (options.dedupeKey) this.dedupeJobs.set(options.dedupeKey, job.id);

    await this.persistOrDegrade();

    const lane = options.lane ?? "background";
    this.queues[lane].push({
      jobId: job.id,
      task: task as (context: JobContext) => Promise<unknown>,
      controller,
      lane,
      ...(options.dedupeKey ? { dedupeKey: options.dedupeKey } : {}),
    });
    this.drain(lane);
    return structuredClone(job);
  }

  get<TResult = unknown>(jobId: string): JobRecord<TResult> | null {
    const job = this.jobs.get(jobId);
    if (!job) return null;
    if (this.finalizingJobs.has(jobId)) {
      return {
        ...structuredClone(job),
        status: "running",
        progress: Math.min(0.99, job.progress),
        message: "Finalizing",
        result: undefined,
        error: undefined,
      } as JobRecord<TResult>;
    }
    return structuredClone(job) as JobRecord<TResult>;
  }

  async cancel(jobId: string): Promise<boolean> {
    await this.initialize();
    const job = this.jobs.get(jobId);
    if (!job || !["queued", "running"].includes(job.status)) return false;
    this.controllers.get(jobId)?.abort(new Error("Cancelled by user."));
    this.update(jobId, {
      status: "cancelled",
      message: "Cancelled",
      progress: job.progress,
    });
    await this.persistOrDegrade();
    return true;
  }

  async prune(maxAgeMs = 24 * 60 * 60_000): Promise<number> {
    await this.initialize();
    const threshold = Date.now() - maxAgeMs;
    let count = 0;
    for (const [jobId, job] of this.jobs) {
      if (["queued", "running"].includes(job.status)) continue;
      if (Date.parse(job.updatedAt) >= threshold) continue;
      this.jobs.delete(jobId);
      this.controllers.delete(jobId);
      count += 1;
    }
    if (count > 0) await this.persistOrDegrade();
    return count;
  }

  async flush(): Promise<void> {
    await this.writeChain;
  }

  async attachPersistence(filePath: string): Promise<void> {
    await this.flush();
    const previousFilePath = this.filePath;
    this.filePath = filePath;
    try {
      await this.persistence.prepare(filePath);
      await this.persist();
    } catch (error) {
      this.filePath = previousFilePath;
      this.reportPersistenceError(error);
      throw error;
    }
  }

  private async load(): Promise<void> {
    if (!this.filePath) return;
    await this.persistence.prepare(this.filePath);
    try {
      const raw = await this.persistence.read(this.filePath);
      const parsed = JSON.parse(raw) as PersistedJobs;
      if (parsed.formatVersion !== 1 || !Array.isArray(parsed.jobs)) {
        throw new Error("Unsupported job database format.");
      }
      for (const record of parsed.jobs) {
        if (!record || typeof record.id !== "string" || typeof record.status !== "string") {
          throw new Error("Invalid job database record.");
        }
        const job = structuredClone(record);
        if (job.status === "running") {
          job.status = "ambiguous";
          job.message = "Server restarted during provider call";
          job.error = {
            code: "SERVER_RESTARTED_DURING_PROVIDER_CALL",
            message: "The server restarted while the provider request was active. Check provider logs and billing before retrying.",
            retryable: false,
          };
          job.updatedAt = new Date().toISOString();
        } else if (job.status === "queued") {
          job.status = "failed";
          job.message = "Server restarted before job start";
          job.error = {
            code: "SERVER_RESTARTED_BEFORE_START",
            message: "The server restarted before the queued request was sent.",
            retryable: true,
          };
          job.updatedAt = new Date().toISOString();
        } else if (job.status === "succeeded" && job.result === undefined) {
          job.status = "failed";
          job.message = "Completed result expired after server restart";
          job.error = {
            code: "SERVER_RESTARTED_AFTER_COMPLETION",
            message: "The provider completed, but Echoes intentionally does not persist memory operation results. Run extraction again after reviewing provider billing.",
            retryable: true,
          };
          job.updatedAt = new Date().toISOString();
        }
        this.jobs.set(job.id, job);
      }
      await this.persist();
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
      await this.persist();
    }
  }

  private drain(lane: JobLane): void {
    const queue = this.queues[lane];
    while (this.activeCount[lane] < this.concurrency[lane] && queue.length > 0) {
      const queued = queue.shift();
      if (!queued) return;
      const job = this.jobs.get(queued.jobId);
      if (!job || job.status !== "queued") {
        this.controllers.delete(queued.jobId);
        if (
          queued.dedupeKey
          && this.dedupeJobs.get(queued.dedupeKey) === queued.jobId
        ) {
          this.dedupeJobs.delete(queued.dedupeKey);
        }
        continue;
      }
      this.activeCount[lane] += 1;
      void this.run(queued).catch((error) => {
        const classified = this.classifyError(error);
        this.update(queued.jobId, {
          status: classified.ambiguous ? "ambiguous" : "failed",
          message: "Internal job runner failure",
          error: {
            code: classified.code,
            message: error instanceof Error ? error.message : String(error),
            retryable: classified.retryable,
          },
        });
        void this.persistOrDegrade();
      }).finally(() => {
        this.activeCount[lane] -= 1;
        if (queued.dedupeKey && this.dedupeJobs.get(queued.dedupeKey) === queued.jobId) {
          this.dedupeJobs.delete(queued.dedupeKey);
        }
        this.drain(lane);
      });
    }
  }

  private async run(queued: QueuedTask): Promise<void> {
    this.update(queued.jobId, { status: "running", progress: 0.01, message: "Started" });
    try {
      await this.persistOrDegrade();
      const result = await queued.task({
        jobId: queued.jobId,
        signal: queued.controller.signal,
        report: (progress, message) => {
          const current = this.jobs.get(queued.jobId);
          if (!current || current.status !== "running") return;
          this.update(queued.jobId, {
            progress: Math.max(0, Math.min(0.99, progress)),
            message,
          });
        },
      });
      if (this.jobs.get(queued.jobId)?.status === "cancelled") return;
      this.finalizingJobs.add(queued.jobId);
      this.update(queued.jobId, {
        status: "succeeded",
        progress: 1,
        message: "Completed",
        result,
      });
    } catch (error) {
      if (this.jobs.get(queued.jobId)?.status === "cancelled") return;
      const classified = this.classifyError(error);
      this.finalizingJobs.add(queued.jobId);
      this.update(queued.jobId, {
        status: classified.ambiguous ? "ambiguous" : "failed",
        message: classified.ambiguous ? "Provider outcome is ambiguous" : "Failed",
        error: {
          code: classified.code,
          message: error instanceof Error ? error.message : String(error),
          retryable: classified.retryable,
        },
      });
    } finally {
      this.controllers.delete(queued.jobId);
      try {
        await this.persistOrDegrade();
      } finally {
        this.finalizingJobs.delete(queued.jobId);
      }
    }
  }

  private classifyError(error: unknown): {
    ambiguous: boolean;
    code: string;
    retryable: boolean;
  } {
    if (error instanceof AmbiguousJobError) {
      return { ambiguous: true, code: error.code, retryable: false };
    }
    const details = error as { code?: unknown; retryable?: unknown; status?: unknown };
    const statusCode = typeof details?.status === "number" ? details.status : null;
    const suppliedCode = typeof details?.code === "string" && /^[A-Z0-9_]{1,100}$/.test(details.code)
      ? details.code
      : null;
    return {
      ambiguous: false,
      code: suppliedCode
        ? suppliedCode
        : statusCode
          ? `PROVIDER_HTTP_${statusCode}`
          : "JOB_FAILED",
      retryable: typeof details?.retryable === "boolean" ? details.retryable : false,
    };
  }

  private update(jobId: string, patch: Partial<JobRecord>): void {
    const current = this.jobs.get(jobId);
    if (!current) return;
    this.jobs.set(jobId, {
      ...current,
      ...patch,
      updatedAt: new Date().toISOString(),
    });
  }

  private persist(): Promise<void> {
    if (!this.filePath) return Promise.resolve();
    const filePath = this.filePath;
    const snapshot: PersistedJobs = {
      formatVersion: 1,
      jobs: [...this.jobs.values()].map((job) => {
        const { result: _memoryResult, ...persisted } = structuredClone(job);
        persisted.message = durableJobMessage(persisted.status);
        if (persisted.error) persisted.error.message = durableErrorMessage(persisted.error);
        return persisted;
      }),
    };
    const operation = this.writeChain.then(() =>
      this.persistence.writeAtomically(filePath, JSON.stringify(snapshot, null, 2)));
    this.writeChain = operation.catch(() => undefined);
    return operation;
  }

  private async persistOrDegrade(): Promise<void> {
    try {
      await this.persist();
    } catch (error) {
      this.filePath = undefined;
      this.reportPersistenceError(error);
    }
  }

  private reportPersistenceError(error: unknown): void {
    const normalized = error instanceof Error ? error : new Error(String(error));
    try {
      this.onPersistenceError?.(normalized);
    } catch {
      // A diagnostic callback must never disrupt provider work.
    }
  }
}
