import type {
  RetrievalDocument,
  RetrievalHit,
  RetrievalSourceWeight,
} from "../../shared/domain";

export interface RankedRetrievalDocument {
  document: RetrievalDocument;
  score: number;
}

function sourcePreference(
  document: RetrievalDocument,
  sourceWeights: RetrievalSourceWeight[] = [],
): { weight: number; order: number } {
  const configured = sourceWeights.find((source) => source.collectionId === document.collectionId);
  return {
    weight: configured?.weight ?? 1,
    order: configured?.order ?? Number.MAX_SAFE_INTEGER,
  };
}

export function reciprocalRankFusion(
  vectorResults: RankedRetrievalDocument[],
  bm25Results: RankedRetrievalDocument[],
  options: { k?: number; limit?: number; sourceWeights?: RetrievalSourceWeight[] } = {},
): RetrievalHit[] {
  const k = options.k ?? 60;
  const limit = options.limit ?? 30;
  const hits = new Map<string, RetrievalHit>();

  const add = (results: RankedRetrievalDocument[], branch: "vector" | "bm25") => {
    for (const [index, result] of results.entries()) {
      const hit = hits.get(result.document.documentId) ?? {
        document: result.document,
        rrfScore: 0,
      };
      hit.rrfScore += 1 / (k + index + 1);
      const preference = sourcePreference(result.document, options.sourceWeights);
      hit.sourceWeight = preference.weight;
      hit.sourceOrder = preference.order;
      if (branch === "vector") hit.vectorScore = result.score;
      else hit.bm25Score = result.score;
      hits.set(result.document.documentId, hit);
    }
  };

  add(vectorResults, "vector");
  add(bm25Results, "bm25");
  return [...hits.values()].map((hit) => ({
    ...hit,
    weightedScore: hit.rrfScore * (hit.sourceWeight ?? 1),
  }))
    .sort((left, right) => (right.weightedScore ?? 0) - (left.weightedScore ?? 0)
      || right.rrfScore - left.rrfScore
      || (left.sourceOrder ?? Number.MAX_SAFE_INTEGER) - (right.sourceOrder ?? Number.MAX_SAFE_INTEGER)
      || left.document.documentId.localeCompare(right.document.documentId))
    .slice(0, limit);
}

export function applyRerankScores(
  hits: RetrievalHit[],
  scores: Array<{ index: number; relevanceScore: number }>,
  limit: number,
): RetrievalHit[] {
  const seen = new Set<number>();
  const reranked: Array<RetrievalHit & { rerankRank: number }> = [];
  for (const result of [...scores].sort((left, right) =>
    right.relevanceScore - left.relevanceScore || left.index - right.index)) {
    if (!Number.isInteger(result.index) || result.index < 0 || result.index >= hits.length) continue;
    if (!Number.isFinite(result.relevanceScore) || seen.has(result.index)) continue;
    seen.add(result.index);
    reranked.push({
      ...hits[result.index]!,
      rerankScore: result.relevanceScore,
      rerankRank: reranked.length,
    });
  }
  const remaining = hits
    .map((hit, index) => ({ hit, index }))
    .filter(({ index }) => !seen.has(index))
    .map(({ hit }, index) => ({ ...hit, rerankRank: reranked.length + index }));
  return [...reranked, ...remaining]
    .map(({ rerankRank, ...hit }) => ({
      ...hit,
      weightedScore: (hit.sourceWeight ?? 1) / (rerankRank + 1),
    }))
    .sort((left, right) => (right.weightedScore ?? 0) - (left.weightedScore ?? 0)
      || (right.rerankScore ?? Number.NEGATIVE_INFINITY)
        - (left.rerankScore ?? Number.NEGATIVE_INFINITY)
      || (left.sourceOrder ?? Number.MAX_SAFE_INTEGER)
        - (right.sourceOrder ?? Number.MAX_SAFE_INTEGER)
      || left.document.documentId.localeCompare(right.document.documentId))
    .slice(0, limit);
}
