import { randomBytes } from "node:crypto";

import type {
  EmbeddingEndpointGroup,
  EndpointTestResult,
  FailoverDecisionRequired,
  RetrievalBranchStatus,
  RetrievalCollection,
  RetrievalCollectionStats,
  RetrievalDocumentStatusResult,
  RetrievalDocumentSyncRequest,
  RetrievalDocumentSyncResult,
  RetrievalHit,
  RetrievalQueryContinueRequest,
  RetrievalQueryContinuation,
  RetrievalQueryRequest,
  RetrievalQueryResult,
  RetrievalEndpoint,
  RerankEndpointSet,
  RetrievalUpsertRequest,
  RetrievalUpsertResult,
} from "../../shared/domain";
import type { JobContext } from "../jobs/job-manager";
import { EndpointHealthRegistry, runEndpointChain } from "./endpoint-failover";
import { applyRerankScores, reciprocalRankFusion } from "./fusion";
import { requestEmbeddings, requestRerank } from "./retrieval-provider";
import { RetrievalStore } from "./retrieval-store";
import type { RankedRetrievalDocument } from "./fusion";

function branch(
  state: RetrievalBranchStatus["state"],
  durationMs = 0,
  message?: string,
): RetrievalBranchStatus {
  return {
    state,
    durationMs,
    attempts: [],
    ...(message ? { message } : {}),
  };
}

interface SearchBranchResult {
  results: RankedRetrievalDocument[];
  status: RetrievalBranchStatus;
  decision?: FailoverDecisionRequired | undefined;
}

type StoredQueryRequest = Omit<
  RetrievalQueryRequest,
  "embeddingGroup" | "rerankSet" | "resumeAfter"
>;

interface QueryContinuationSnapshot {
  provider: "embedding" | "rerank";
  failedEndpointId: string;
  endpointConfiguration: string;
  expiresAt: number;
  request: StoredQueryRequest;
  bm25: SearchBranchResult;
  vector: SearchBranchResult;
  fusedHits?: RetrievalHit[] | undefined;
  rerankStatus?: RetrievalBranchStatus | undefined;
}

const CONTINUATION_TTL_MS = 10 * 60_000;
const MAX_QUERY_CONTINUATIONS = 128;

export class RetrievalService {
  private readonly embeddingHealth = new EndpointHealthRegistry();
  private readonly rerankHealth = new EndpointHealthRegistry();
  private readonly queryContinuations = new Map<string, QueryContinuationSnapshot>();

  constructor(
    readonly store: RetrievalStore,
    private readonly resolveEndpoint: <T extends RetrievalEndpoint>(endpoint: T) => Promise<T> =
      async (endpoint) => structuredClone(endpoint),
  ) {}

  async listCollectionStats(): Promise<RetrievalCollectionStats[]> {
    const collections = await this.store.listCollections();
    return Promise.all(collections.map((collection) => this.store.collectionStats(collection)));
  }

  createCollection(
    input: Pick<RetrievalCollection, "id" | "name" | "description" | "embeddingSpaceId" | "dimensions">,
  ): Promise<RetrievalCollection> {
    return this.store.createCollection(input);
  }

  deleteCollection(collectionId: string): Promise<boolean> {
    return this.store.deleteCollection(collectionId);
  }

  deleteDocuments(documentIds: string[]): Promise<number> {
    return this.store.deleteDocuments(documentIds);
  }

  async documentStatus(documentIds: string[]): Promise<RetrievalDocumentStatusResult> {
    const documents = await this.store.getDocuments(documentIds);
    return {
      documents: documents.map(({ documentId, collectionId, contentHash, vectorState, updatedAt }) => ({
        documentId,
        collectionId,
        contentHash,
        vectorState,
        updatedAt,
      })),
    };
  }

  async syncDocuments(
    request: RetrievalDocumentSyncRequest,
    context: JobContext,
  ): Promise<RetrievalDocumentSyncResult> {
    if (request.documents.length > 0) {
      await this.assertCollectionCompatibility(
        [...new Set(request.documents.map((document) => document.collectionId))],
        request.embeddingGroup,
      );
    }
    context.report(0.03, "Removing obsolete documents");
    const deleted = await this.deleteDocuments(request.deleteDocumentIds);
    if (request.documents.length === 0) {
      return {
        deleted,
        created: 0,
        updated: 0,
        unchanged: 0,
        vectorized: 0,
        pending: 0,
        failed: 0,
        ambiguous: 0,
        attempts: [],
      };
    }
    const result = await this.upsert(request, context);
    return { ...result, deleted };
  }

  async upsert(request: RetrievalUpsertRequest, context: JobContext): Promise<RetrievalUpsertResult> {
    context.report(0.05, "Saving authoritative documents");
    await this.assertCollectionCompatibility(
      [...new Set(request.documents.map((document) => document.collectionId))],
      request.embeddingGroup,
    );
    const prepared = await this.store.prepareUpsert(request.documents);
    const base: RetrievalUpsertResult = {
      created: prepared.created,
      updated: prepared.updated,
      unchanged: prepared.unchanged,
      vectorized: 0,
      pending: prepared.needsEmbedding.length,
      failed: 0,
      ambiguous: 0,
      attempts: [],
    };
    if (prepared.needsEmbedding.length === 0 || !request.embeddingGroup) return base;

    context.report(0.2, `Embedding ${prepared.needsEmbedding.length} documents`);
    const result = await runEndpointChain({
      provider: "embedding",
      endpoints: request.embeddingGroup.endpoints,
      policy: request.failoverPolicy,
      resumeAfterEndpointId: request.resumeAfterEndpointId,
      health: this.embeddingHealth,
      signal: context.signal,
      resolveEndpoint: this.resolveEndpoint,
      invoke: (endpoint) => requestEmbeddings({
        endpoint,
        texts: prepared.needsEmbedding.map((document) => document.text),
        expectedDimensions: request.embeddingGroup!.dimensions,
        signal: context.signal,
      }),
    });
    base.attempts = result.attempts;
    const documentIds = prepared.needsEmbedding.map((document) => document.documentId);
    if (result.state === "succeeded" && result.value) {
      await this.store.upsertVectors({
        embeddingSpaceId: request.embeddingGroup.embeddingSpaceId,
        dimensions: request.embeddingGroup.dimensions,
        documents: prepared.needsEmbedding,
        vectors: result.value,
      });
      await this.store.markVectorState(documentIds, "ready");
      return { ...base, vectorized: documentIds.length, pending: 0 };
    }

    const state = result.state === "ambiguous" ? "ambiguous" : "failed";
    await this.store.markVectorState(documentIds, state);
    return {
      ...base,
      pending: 0,
      failed: state === "failed" ? documentIds.length : 0,
      ambiguous: state === "ambiguous" ? documentIds.length : 0,
      ...(result.decisionRequired ? { decisionRequired: result.decisionRequired } : {}),
    };
  }

  async rebuild(options: {
    collectionIds: string[];
    embeddingGroup: EmbeddingEndpointGroup;
    failoverPolicy: RetrievalUpsertRequest["failoverPolicy"];
    resumeAfterEndpointId?: string | undefined;
    onlyUnready?: boolean | undefined;
  }, context: JobContext): Promise<RetrievalUpsertResult> {
    await this.assertCollectionCompatibility(options.collectionIds, options.embeddingGroup);
    const stats = await this.listCollectionStats();
    const selectedStats = stats.filter((item) => options.collectionIds.includes(item.collection.id));
    const total = selectedStats.reduce(
      (sum, item) => sum + (options.onlyUnready
        ? item.pending + item.failed + item.ambiguous
        : item.documents),
      0,
    );
    const summary: RetrievalUpsertResult = {
      created: 0,
      updated: 0,
      unchanged: total,
      vectorized: 0,
      pending: total,
      failed: 0,
      ambiguous: 0,
      attempts: [],
    };
    let processed = 0;

    const states = options.onlyUnready ? ["pending", "failed", "ambiguous"] as const : [];
    for await (const documents of this.store.documentBatches(options.collectionIds, 32, [...states])) {
      if (context.signal.aborted) throw context.signal.reason ?? new Error("Cancelled.");
      context.report(total === 0 ? 0.9 : Math.min(0.9, processed / total), `Embedding ${processed}/${total}`);
      const result = await runEndpointChain({
        provider: "embedding",
        endpoints: options.embeddingGroup.endpoints,
        policy: options.failoverPolicy,
        resumeAfterEndpointId: options.resumeAfterEndpointId,
        health: this.embeddingHealth,
        signal: context.signal,
        resolveEndpoint: this.resolveEndpoint,
        invoke: (endpoint) => requestEmbeddings({
          endpoint,
          texts: documents.map((document) => document.text),
          expectedDimensions: options.embeddingGroup.dimensions,
          signal: context.signal,
        }),
      });
      summary.attempts.push(...result.attempts.slice(-10));
      const ids = documents.map((document) => document.documentId);
      if (result.state === "succeeded" && result.value) {
        await this.store.upsertVectors({
          embeddingSpaceId: options.embeddingGroup.embeddingSpaceId,
          dimensions: options.embeddingGroup.dimensions,
          documents,
          vectors: result.value,
        });
        await this.store.markVectorState(ids, "ready");
        summary.vectorized += ids.length;
        summary.pending -= ids.length;
        processed += ids.length;
        continue;
      }

      const state = result.state === "ambiguous" ? "ambiguous" : "failed";
      await this.store.markVectorState(ids, state);
      summary.pending -= ids.length;
      if (state === "ambiguous") summary.ambiguous += ids.length;
      else summary.failed += ids.length;
      if (result.decisionRequired) summary.decisionRequired = result.decisionRequired;
      break;
    }
    await this.store.optimize();
    return summary;
  }

  async query(request: RetrievalQueryRequest, context: JobContext): Promise<RetrievalQueryResult> {
    const vectorCollectionIds = request.vectorCollectionIds ?? request.collectionIds;
    await this.assertCollectionsExist(request.collectionIds);
    if (request.vectorEnabled && vectorCollectionIds.length > 0) {
      await this.assertCollectionCompatibility(vectorCollectionIds, request.embeddingGroup);
    }
    context.report(0.08, "Running retrieval branches");

    const bm25Task: Promise<SearchBranchResult> = request.bm25Enabled
      ? this.runBm25(request)
      : Promise.resolve({ results: [], status: branch("disabled") });
    const vectorTask: Promise<SearchBranchResult> = request.vectorEnabled
      && request.embeddingGroup
      && vectorCollectionIds.length > 0
      ? this.runVector(request, context)
      : Promise.resolve({ results: [], status: branch("disabled") });
    const [bm25, vector] = await Promise.all([bm25Task, vectorTask]);
    const hits = this.fuse(request, vector.results, bm25.results);

    if (vector.decision) {
      const continuation = this.saveContinuation({
        provider: "embedding",
        failedEndpointId: vector.decision.failedEndpointId,
        endpointConfiguration: this.endpointConfiguration(request.embeddingGroup!),
        request: this.withoutCredentials(request),
        bm25,
        vector,
      });
      return this.result(request, hits, vector, bm25, branch("disabled"), {
        decisionRequired: vector.decision,
        continuation,
      });
    }

    return this.finishRerank(request, hits, vector, bm25, context);
  }

  async continueQuery(
    input: RetrievalQueryContinueRequest,
    context: JobContext,
  ): Promise<RetrievalQueryResult> {
    this.pruneContinuations();
    const snapshot = this.queryContinuations.get(input.token);
    if (!snapshot || snapshot.expiresAt <= Date.now()) {
      this.queryContinuations.delete(input.token);
      throw Object.assign(new Error("The retrieval continuation has expired."), { statusCode: 410 });
    }
    const request: RetrievalQueryRequest = {
      ...snapshot.request,
      failoverPolicy: input.failoverPolicy,
      ...(input.embeddingGroup ? { embeddingGroup: input.embeddingGroup } : {}),
      ...(input.rerankSet ? { rerankSet: input.rerankSet } : {}),
    };
    if (snapshot.provider === "embedding") {
      if (!input.embeddingGroup) {
        throw Object.assign(new Error("Embedding continuation requires the original endpoint group."), {
          statusCode: 400,
        });
      }
      if (this.endpointConfiguration(input.embeddingGroup) !== snapshot.endpointConfiguration) {
        throw Object.assign(new Error("Embedding continuation endpoint configuration changed."), {
          statusCode: 409,
        });
      }
      await this.assertCollectionCompatibility(
        request.vectorCollectionIds ?? request.collectionIds,
        input.embeddingGroup,
      );
      this.claimContinuation(input.token, snapshot);
      request.resumeAfter = { embeddingEndpointId: snapshot.failedEndpointId };
      const continuedVector = await this.runVector(request, context);
      const vector = {
        ...continuedVector,
        status: this.mergeBranchStatus(snapshot.vector.status, continuedVector.status),
      };
      const hits = this.fuse(request, vector.results, snapshot.bm25.results);
      if (vector.decision) {
        const continuation = this.saveContinuation({
          provider: "embedding",
          failedEndpointId: vector.decision.failedEndpointId,
          endpointConfiguration: this.endpointConfiguration(request.embeddingGroup!),
          request: this.withoutCredentials(request),
          bm25: snapshot.bm25,
          vector,
        });
        return this.result(request, hits, vector, snapshot.bm25, branch("disabled"), {
          decisionRequired: vector.decision,
          continuation,
        });
      }
      return this.finishRerank(request, hits, vector, snapshot.bm25, context);
    }

    if (!input.rerankSet) {
      throw Object.assign(new Error("Rerank continuation requires the original endpoint set."), {
        statusCode: 400,
      });
    }
    if (this.endpointConfiguration(input.rerankSet) !== snapshot.endpointConfiguration) {
      throw Object.assign(new Error("Rerank continuation endpoint configuration changed."), {
        statusCode: 409,
      });
    }
    this.claimContinuation(input.token, snapshot);
    request.resumeAfter = { rerankEndpointId: snapshot.failedEndpointId };
    return this.finishRerank(
      request,
      snapshot.fusedHits ?? [],
      snapshot.vector,
      snapshot.bm25,
      context,
      snapshot.rerankStatus,
    );
  }

  private async finishRerank(
    request: RetrievalQueryRequest,
    fusedHits: RetrievalHit[],
    vector: SearchBranchResult,
    bm25: SearchBranchResult,
    context: JobContext,
    previousStatus?: RetrievalBranchStatus,
  ): Promise<RetrievalQueryResult> {
    if (!request.rerankEnabled || !request.rerankSet || fusedHits.length === 0) {
      return this.result(request, fusedHits, vector, bm25, branch("disabled"));
    }
    context.report(0.72, "Reranking fused results");
    const startedAt = Date.now();
    const candidates = fusedHits.slice(0, request.rerankTopK);
    const rerank = await runEndpointChain({
      provider: "rerank",
      endpoints: request.rerankSet.endpoints,
      policy: request.failoverPolicy,
      resumeAfterEndpointId: request.resumeAfter?.rerankEndpointId,
      health: this.rerankHealth,
      signal: context.signal,
      resolveEndpoint: this.resolveEndpoint,
      invoke: (endpoint) => requestRerank({
        endpoint,
        query: request.query,
        documents: candidates.map((hit) => hit.document.text),
        signal: context.signal,
      }),
    });
    let rerankStatus: RetrievalBranchStatus = {
      state: rerank.state,
      durationMs: Date.now() - startedAt,
      attempts: rerank.attempts,
      ...(rerank.message ? { message: rerank.message } : {}),
    };
    if (previousStatus) rerankStatus = this.mergeBranchStatus(previousStatus, rerankStatus);
    if (rerank.state === "succeeded" && rerank.value) {
      const hits = applyRerankScores(fusedHits, rerank.value, request.finalTopK);
      return this.result(request, hits, vector, bm25, rerankStatus);
    }
    if (rerank.decisionRequired) {
      const continuation = this.saveContinuation({
        provider: "rerank",
        failedEndpointId: rerank.decisionRequired.failedEndpointId,
        endpointConfiguration: this.endpointConfiguration(request.rerankSet),
        request: this.withoutCredentials(request),
        bm25,
        vector,
        fusedHits,
        rerankStatus,
      });
      return this.result(request, fusedHits, vector, bm25, rerankStatus, {
        decisionRequired: rerank.decisionRequired,
        continuation,
      });
    }
    return this.result(request, fusedHits, vector, bm25, rerankStatus);
  }

  private result(
    request: RetrievalQueryRequest,
    hits: RetrievalHit[],
    vector: SearchBranchResult,
    bm25: SearchBranchResult,
    rerank: RetrievalBranchStatus,
    optional: {
      decisionRequired?: FailoverDecisionRequired | undefined;
      continuation?: RetrievalQueryContinuation | undefined;
    } = {},
  ): RetrievalQueryResult {
    return {
      hits: hits.slice(0, request.finalTopK),
      branches: { vector: vector.status, bm25: bm25.status, rerank },
      ...optional,
    };
  }

  private fuse(
    request: RetrievalQueryRequest,
    vector: RankedRetrievalDocument[],
    bm25: RankedRetrievalDocument[],
  ): RetrievalHit[] {
    return reciprocalRankFusion(vector, bm25, {
      k: 60,
      limit: Math.max(request.finalTopK, request.rerankTopK),
      ...(request.sourceWeights ? { sourceWeights: request.sourceWeights } : {}),
    });
  }

  private withoutCredentials(request: RetrievalQueryRequest): StoredQueryRequest {
    const {
      embeddingGroup: _embeddingGroup,
      rerankSet: _rerankSet,
      resumeAfter: _resumeAfter,
      ...stored
    } = request;
    return structuredClone(stored);
  }

  private endpointConfiguration(group: EmbeddingEndpointGroup | RerankEndpointSet): string {
    return JSON.stringify({
      id: group.id,
      name: group.name,
      ...("embeddingSpaceId" in group ? {
        embeddingSpaceId: group.embeddingSpaceId,
        dimensions: group.dimensions,
      } : {}),
      endpoints: group.endpoints.map(({ apiKey: _apiKey, ...endpoint }) => endpoint),
    });
  }

  private claimContinuation(token: string, snapshot: QueryContinuationSnapshot): void {
    if (this.queryContinuations.get(token) !== snapshot) {
      throw Object.assign(new Error("The retrieval continuation was already used."), { statusCode: 410 });
    }
    this.queryContinuations.delete(token);
  }

  private saveContinuation(
    snapshot: Omit<QueryContinuationSnapshot, "expiresAt">,
  ): RetrievalQueryContinuation {
    this.pruneContinuations();
    while (this.queryContinuations.size >= MAX_QUERY_CONTINUATIONS) {
      const oldestToken = this.queryContinuations.keys().next().value as string | undefined;
      if (!oldestToken) break;
      this.queryContinuations.delete(oldestToken);
    }
    const token = randomBytes(32).toString("hex");
    const expiresAt = Date.now() + CONTINUATION_TTL_MS;
    this.queryContinuations.set(token, {
      ...structuredClone(snapshot),
      expiresAt,
    });
    return {
      token,
      provider: snapshot.provider,
      failedEndpointId: snapshot.failedEndpointId,
      expiresAt: new Date(expiresAt).toISOString(),
    };
  }

  private pruneContinuations(): void {
    const now = Date.now();
    for (const [token, snapshot] of this.queryContinuations) {
      if (snapshot.expiresAt <= now) this.queryContinuations.delete(token);
    }
  }

  private mergeBranchStatus(
    previous: RetrievalBranchStatus,
    current: RetrievalBranchStatus,
  ): RetrievalBranchStatus {
    return {
      ...current,
      durationMs: previous.durationMs + current.durationMs,
      attempts: [...previous.attempts, ...current.attempts],
    };
  }

  async testEndpoint(options: {
    kind: "embedding" | "rerank";
    endpoint: EmbeddingEndpointGroup["endpoints"][number];
    expectedDimensions?: number | undefined;
  }, context: JobContext): Promise<EndpointTestResult> {
    const startedAt = Date.now();
    const result = await runEndpointChain({
      provider: options.kind,
      endpoints: [{ ...options.endpoint, enabled: true }],
      policy: "definitive_only",
      signal: context.signal,
      resolveEndpoint: this.resolveEndpoint,
      invoke: async (endpoint) => {
        if (options.kind === "embedding") {
          return (await requestEmbeddings({
            endpoint,
            texts: ["Echoes endpoint health check"],
            expectedDimensions: options.expectedDimensions!,
            signal: context.signal,
          }))[0]!;
        }
        return requestRerank({
          endpoint,
          query: "Echoes health check",
          documents: ["Echoes health check", "Unrelated text"],
          signal: context.signal,
        });
      },
    });
    if (result.state !== "succeeded" || !result.value) {
      const error = Object.assign(new Error(result.message ?? "Endpoint test failed."), {
        code: result.state === "ambiguous" ? "AMBIGUOUS_PROVIDER_OUTCOME" : "ENDPOINT_TEST_FAILED",
      });
      throw error;
    }
    return {
      endpointId: options.endpoint.id,
      kind: options.kind,
      latencyMs: Date.now() - startedAt,
      ...(options.kind === "embedding" ? { dimensions: (result.value as number[]).length } : {}),
      attempts: result.attempts,
    };
  }

  private async runBm25(request: RetrievalQueryRequest) {
    const startedAt = Date.now();
    try {
      const results = await this.store.searchBm25(
        request.query,
        request.collectionIds,
        request.bm25TopK,
        request.excludeSourceIds,
      );
      return { results, status: branch("succeeded", Date.now() - startedAt) };
    } catch (error) {
      return {
        results: [],
        status: branch("failed", Date.now() - startedAt, error instanceof Error ? error.message : String(error)),
      };
    }
  }

  private async runVector(request: RetrievalQueryRequest, context: JobContext) {
    const startedAt = Date.now();
    const group = request.embeddingGroup!;
    const embedded = await runEndpointChain({
      provider: "embedding",
      endpoints: group.endpoints,
      policy: request.failoverPolicy,
      resumeAfterEndpointId: request.resumeAfter?.embeddingEndpointId,
      health: this.embeddingHealth,
      signal: context.signal,
      resolveEndpoint: this.resolveEndpoint,
      invoke: async (endpoint) => (await requestEmbeddings({
        endpoint,
        texts: [request.query],
        expectedDimensions: group.dimensions,
        signal: context.signal,
      }))[0]!,
    });
    if (embedded.state !== "succeeded" || !embedded.value) {
      return {
        results: [],
        status: {
          state: embedded.state,
          durationMs: Date.now() - startedAt,
          attempts: embedded.attempts,
          ...(embedded.message ? { message: embedded.message } : {}),
        } satisfies RetrievalBranchStatus,
        decision: embedded.decisionRequired,
      };
    }
    try {
      const results = await this.store.searchVector({
        embeddingSpaceId: group.embeddingSpaceId,
        queryVector: embedded.value,
        collectionIds: request.vectorCollectionIds ?? request.collectionIds,
        limit: request.vectorTopK,
        excludeSourceIds: request.excludeSourceIds,
      });
      return {
        results,
        status: {
          state: "succeeded" as const,
          durationMs: Date.now() - startedAt,
          attempts: embedded.attempts,
        },
        decision: undefined,
      };
    } catch (error) {
      return {
        results: [],
        status: {
          state: "failed" as const,
          durationMs: Date.now() - startedAt,
          attempts: embedded.attempts,
          message: error instanceof Error ? error.message : String(error),
        },
        decision: undefined,
      };
    }
  }

  private async assertCollectionsExist(collectionIds: string[]): Promise<RetrievalCollection[]> {
    const collections = await this.store.listCollections();
    const selected = collections.filter((collection) => collectionIds.includes(collection.id));
    if (selected.length !== new Set(collectionIds).size) {
      throw Object.assign(new Error("One or more retrieval collections do not exist."), { statusCode: 404 });
    }
    return selected;
  }

  private async assertCollectionCompatibility(
    collectionIds: string[],
    group?: EmbeddingEndpointGroup,
  ): Promise<void> {
    const collections = await this.assertCollectionsExist(collectionIds);
    if (!group) return;
    const mismatch = collections.find((collection) => collection.embeddingSpaceId !== group.embeddingSpaceId
      || collection.dimensions !== group.dimensions);
    if (mismatch) {
      throw Object.assign(
        new Error(`Collection ${mismatch.id} is not compatible with embedding space ${group.embeddingSpaceId}.`),
        { statusCode: 409 },
      );
    }
  }
}
